 internal static int Run(){int count=0;Action<bool,string>check=(ok,name)=>{if(!ok)throw new Exception(name);count++;};var body=new Rigidbody{mass=3,drag=0.2f,angularDrag=0.4f,useGravity=false,constraints=RigidbodyConstraints.FreezePositionX,interpolation=RigidbodyInterpolation.Interpolate,collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic,velocity=new Vector3(2,3,4),angularVelocity=new Vector3(1,2,3)};check(RebirthNpcNativeRigidbodyState.TryCapture(body,out var saved),"actual original dynamics captured");var changed=saved.Write();changed.SetAttributeValue("mass",9);check((string)saved.Write().Attribute("mass")=="3","immutable dynamics");foreach(var pair in new[]{("version","2"),("mass","0"),("mass","NaN"),("drag","-1"),("angularDrag","Infinity"),("gravity","true"),("constraints","1"),("interpolation","3"),("collision","4"),("vx","01"),("ax","NaN")}){var bad=saved.Write();bad.SetAttributeValue(pair.Item1,pair.Item2);check(!RebirthNpcNativeRigidbodyState.TryRead(bad,out _),"invalid dynamics "+pair.Item1);}
